    src = """
    @u.quantity_input
    def myfunc_args(solarx: {0}, solary: {1}):
        return solarx, solary

    solarx, solary = myfunc_args(1*u.arcsec, 1*u.arcsec)

    assert isinstance(solarx, u.Quantity)
    assert isinstance(solary, u.Quantity)

