# Simulate the quantity_input decorator logic based on the fix
class MockUnit:
    """Mock unit for testing"""
    def __init__(self, name):
        self.name = name

    def to(self, target_unit):
        return f"converted to {target_unit.name}"


def mock_quantity_input(wrapped_function):
    """Simulates the key part of quantity_input decorator"""
    wrapped_signature = inspect.signature(wrapped_function)

    @wraps(wrapped_function)
    def wrapper(*func_args, **func_kwargs):
        return_ = wrapped_function(*func_args, **func_kwargs)

        # This is the FIXED code - adding check for None
        if wrapped_signature.return_annotation is not inspect.Signature.empty and wrapped_signature.return_annotation is not None:
            return return_.to(wrapped_signature.return_annotation)
        else:
            return return_

    return wrapper


# Test cases
print("=" * 60)
print("Test 1: Function with -> None annotation (constructor style)")
print("=" * 60)

